import{_ as e,H as a,f as l,i as s}from"./chunks/framework.DLd0CbzH.js";const g=JSON.parse('{"title":"Архитектура и стек — Agelto","description":"","frontmatter":{"type":"architecture","tags":["agelto","architecture","laravel","ai","pgvector"],"created":"2026-05-31T00:00:00.000Z","updated":"2026-06-13T00:00:00.000Z"},"headers":[],"relativePath":"03_Dev/Architecture_Agelto.md","filePath":"03_Dev/Architecture_Agelto.md"}'),i={name:"03_Dev/Architecture_Agelto.md"};function n(o,t,r,d,c,p){return a(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="архитектура-и-стек-—-agelto" tabindex="-1">Архитектура и стек — Agelto <a class="header-anchor" href="#архитектура-и-стек-—-agelto" aria-label="Permalink to &quot;Архитектура и стек — Agelto&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">Связанные документы</p><p>← [[BRD (Agelto)]] | ← [[Agelto]] | → [[Dev_Status]] | → [[Risk_Register (Agelto)]] | → [[Procurement_Lifecycle]] | → [[ADR-001_Catalog_From_TcenZor]]</p><p>Источник истины по реализации — код <code>/home/vostrikov/projects/agelto/agelto/</code> (синхронизировано 2026-06-11)</p></div><div class="important custom-block github-alert"><p class="custom-block-title">Эталонный каталог — внешний (из [[TcenZor]])</p><p>Решением [[ADR-001_Catalog_From_TcenZor|ADR-001]] Agelto <strong>не строит</strong> собственный эталонный MDM. Эталонный строительный каталог (категории/эталоны/ алиасы/ГОСТ·ОКПД2·КТРУ) приходит из [[TcenZor]] по API ([[Universal_Catalog_Architecture]]). Agelto матчит сметы к этому эталону.</p></div><hr><h2 id="_1-общая-схема-системы" tabindex="-1">1. Общая схема системы <a class="header-anchor" href="#_1-общая-схема-системы" aria-label="Permalink to &quot;1. Общая схема системы&quot;">​</a></h2><p>Реализованный конвейер — 4 стадии (код: <code>app/Process/*</code>, описание: <code>docs/workflow/parsing-process.md</code> в репозитории):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ЕИС (zakupki.gov.ru)</span></span>
<span class="line"><span>  │  HTTP (headless Chrome + прокси)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>[Стадия 1: Crawling] — Модуль Eis (EisCrawlingService) поверх Platform/Crawlers</span></span>
<span class="line"><span>  │  CrawlingItemDto → plt_crawler_links (status: pending)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>[Стадия 2: DocParsing] — индексация вложений карточки закупки</span></span>
<span class="line"><span>  │  Фильтр по ключевым словам («смета», «ЛСР», «локальный») → plt_crawler_link_attachments</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>[Стадия 3: PrimaryAnalysis] — AI-скрининг (PrimaryAnalysisJob)</span></span>
<span class="line"><span>  │  Gemini: «это смета СМР? сумма?» (Excel: первые строки в HTML; PDF: первая страница)</span></span>
<span class="line"><span>  │  → PrimaryAnalyzed | PrimaryIgnored</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>[Стадия 4: EstimateAnalysis] — глубокий парсинг (EstimateAnalysisJob)</span></span>
<span class="line"><span>  │  Чанковая обработка по 80 строк → позиции в plt_document_analysis_responses (JSON)</span></span>
<span class="line"><span>  │  Нормализация в ord_* (Стадия 5 OrderParsing) — НЕ подключена (OrderParsingProcess::run() пуст)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>[Semantic Matcher] — pgvector (не начат)</span></span>
<span class="line"><span>  │  Cosine similarity: позиция сметы → ЭТАЛОН (каталог TcenZor) → коллекция поставщика</span></span>
<span class="line"><span>  │  (эталон — внешний из TcenZor, ADR-001; матчинг идёт через эталонный слой,</span></span>
<span class="line"><span>  │   а не напрямую смета ↔ коллекция)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>[Lead Scorer] — ранжирование (не начат)</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>[CRM Integration] — Bitrix24 / amoCRM API (не начата)</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">Двухступенчатый матчинг через эталон</p><p>Раньше предполагалось связывать позицию сметы напрямую с коллекцией клиента. По [[ADR-001_Catalog_From_TcenZor|ADR-001]] вводится промежуточный эталонный слой: <strong>позиция сметы → эталонный товар TcenZor → позиция коллекции клиента</strong>. Это даёт переиспользуемые алиасы и нормативку вместо матчинга по случайному тексту наименования.</p></div><p>Стадии связываются через <code>Bus::chain()</code> (afterCommit); каждый job имеет idempotency guard — проверку статуса перед выполнением.</p><hr><h2 id="_2-технологическии-стек" tabindex="-1">2. Технологический стек <a class="header-anchor" href="#_2-технологическии-стек" aria-label="Permalink to &quot;2. Технологический стек&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Слой</th><th style="text-align:left;">Технология</th><th style="text-align:left;">Версия</th></tr></thead><tbody><tr><td style="text-align:left;">Backend</td><td style="text-align:left;">PHP / Laravel</td><td style="text-align:left;">8.5 / 12</td></tr><tr><td style="text-align:left;">Auth</td><td style="text-align:left;">Laravel Fortify (+2FA TOTP)</td><td style="text-align:left;">v1</td></tr><tr><td style="text-align:left;">Модули</td><td style="text-align:left;">nWidart/laravel-modules</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Admin Panel</td><td style="text-align:left;">Filament</td><td style="text-align:left;">v5</td></tr><tr><td style="text-align:left;">Frontend</td><td style="text-align:left;">Inertia.js + Vue 3</td><td style="text-align:left;">v2 / v3</td></tr><tr><td style="text-align:left;">Роутинг фронтенда</td><td style="text-align:left;">Laravel Wayfinder</td><td style="text-align:left;">v0</td></tr><tr><td style="text-align:left;">Очереди</td><td style="text-align:left;">Laravel Horizon</td><td style="text-align:left;">v5</td></tr><tr><td style="text-align:left;">AI (документы)</td><td style="text-align:left;">Gemini 2.0 Flash (Google API)</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Media Storage</td><td style="text-align:left;">Spatie Media Library</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">БД</td><td style="text-align:left;">SQLite (dev) / PostgreSQL (prod)</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Векторный поиск</td><td style="text-align:left;">pgvector (планируется)</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Браузер</td><td style="text-align:left;">BrowserService (headless)</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Прокси</td><td style="text-align:left;">Ротируемый пул (Sys module)</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Контейнеризация</td><td style="text-align:left;">Docker / Docker Compose (prod: Swarm secrets)</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Стиль кода</td><td style="text-align:left;">Pint + PHPStan/Larastan</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Тесты</td><td style="text-align:left;">Pest v4 + architecture tests (<code>tests/Unit/ArchTest.php</code>)</td><td style="text-align:left;">—</td></tr></tbody></table><hr><h2 id="_3-модульная-структура-nwidart-laravel-modules" tabindex="-1">3. Модульная структура (nWidart/laravel-modules) <a class="header-anchor" href="#_3-модульная-структура-nwidart-laravel-modules" aria-label="Permalink to &quot;3. Модульная структура (nWidart/laravel-modules)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Модуль</th><th style="text-align:left;">Назначение</th><th style="text-align:left;">Статус</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Sys</strong></td><td style="text-align:left;">Прокси-пул, системные логи</td><td style="text-align:left;">рабочий</td></tr><tr><td style="text-align:left;"><strong>Platform</strong></td><td style="text-align:left;">Кроулеры, Document Analysis, Prompt Rules</td><td style="text-align:left;">рабочий</td></tr><tr><td style="text-align:left;"><strong>Eis</strong></td><td style="text-align:left;">Парсер zakupki.gov.ru</td><td style="text-align:left;">рабочий</td></tr></tbody></table><hr><h2 id="_4-модуль-sys-—-инфраструктура" tabindex="-1">4. Модуль Sys — Инфраструктура <a class="header-anchor" href="#_4-модуль-sys-—-инфраструктура" aria-label="Permalink to &quot;4. Модуль Sys — Инфраструктура&quot;">​</a></h2><h3 id="_4-1-прокси-менеджмент" tabindex="-1">4.1 Прокси-менеджмент <a class="header-anchor" href="#_4-1-прокси-менеджмент" aria-label="Permalink to &quot;4.1 Прокси-менеджмент&quot;">​</a></h3><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><p><strong>ProxyRepository</strong> — предоставляет активный прокси для каждого запроса.</p><h3 id="_4-2-логирование" tabindex="-1">4.2 Логирование <a class="header-anchor" href="#_4-2-логирование" aria-label="Permalink to &quot;4.2 Логирование&quot;">​</a></h3><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><p><strong>AppLogger</strong> — обёртка над стандартным Logger с поддержкой <code>LogOutput::Console</code> и <code>LogOutput::DB</code>.</p><hr><h2 id="_5-модуль-platform-—-ядро" tabindex="-1">5. Модуль Platform — Ядро <a class="header-anchor" href="#_5-модуль-platform-—-ядро" aria-label="Permalink to &quot;5. Модуль Platform — Ядро&quot;">​</a></h2><h3 id="_5-1-платформы" tabindex="-1">5.1 Платформы <a class="header-anchor" href="#_5-1-платформы" aria-label="Permalink to &quot;5.1 Платформы&quot;">​</a></h3><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><h3 id="_5-2-кроулеры" tabindex="-1">5.2 Кроулеры <a class="header-anchor" href="#_5-2-кроулеры" aria-label="Permalink to &quot;5.2 Кроулеры&quot;">​</a></h3><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><p><strong>AbstractCrawlingService:</strong></p><ul><li><code>startHook(url)</code> — точка входа, дробление задания</li><li><code>crawlingPage(url)</code> — обход одной страницы</li><li><code>crawlingItem(node)</code> → <code>CrawlingItemDto</code></li><li><code>parseAttachments(url)</code> → <code>AttachmentDto[]</code></li><li><code>keepStateOnCrash</code> — восстановление после сбоя</li></ul><h3 id="_5-3-кроулинг-—-ссылки-вложения-прогоны-аналитика" tabindex="-1">5.3 Кроулинг — ссылки, вложения, прогоны, аналитика <a class="header-anchor" href="#_5-3-кроулинг-—-ссылки-вложения-прогоны-аналитика" aria-label="Permalink to &quot;5.3 Кроулинг — ссылки, вложения, прогоны, аналитика&quot;">​</a></h3><blockquote><p>Сверено с миграциями (Вариант A). Сквозной error-блок (<code>attempts, last_error, last_error_at, next_retry_at, failed_permanently</code>) — на всех воркер-таблицах.</p></blockquote><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><h3 id="_5-4-элементы-парсинга-—-удалено" tabindex="-1">5.4 Элементы парсинга — УДАЛЕНО <a class="header-anchor" href="#_5-4-элементы-парсинга-—-удалено" aria-label="Permalink to &quot;5.4 Элементы парсинга — УДАЛЕНО&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">Удалено в редизайне БД (Вариант A)</p><p>Таблицы <code>plt_parsing_items</code> / <code>plt_parsing_item_attachments</code> (модели <code>Parsing\\*</code>) были мёртвой параллельной веткой (см. <code>AUDIT.md</code> D2) и <strong>удалены</strong>. Единица работы AI-пайплайна — связка <code>LinkAttachment → DocumentAnalysis</code> (§5.5). Позиции сметы Стадии 4 пишутся в <code>plt_document_analysis_responses</code> (JSON); нормализация в <code>ord_*</code> — Стадия 5 (<code>OrderParsing</code>), которая <strong>не подключена</strong>.</p></div><h3 id="_5-5-documentanalysis-—-ai-паиплаин" tabindex="-1">5.5 DocumentAnalysis — AI-пайплайн <a class="header-anchor" href="#_5-5-documentanalysis-—-ai-паиплаин" aria-label="Permalink to &quot;5.5 DocumentAnalysis — AI-пайплайн&quot;">​</a></h3><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><h3 id="_5-6-promptrules" tabindex="-1">5.6 PromptRules <a class="header-anchor" href="#_5-6-promptrules" aria-label="Permalink to &quot;5.6 PromptRules&quot;">​</a></h3><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><p><strong>QA-регламент изменения промптов</strong> (закрывает риск тихой деградации качества — [[Risk_Register (Agelto)]] R-8):</p><ol><li>Изменение → новая версия (уже в коде: <code>unique(key, version)</code>), старая не редактируется</li><li>Перед активацией — прогон по golden dataset (эталонные сметы с ожидаемым JSON; собрать ≥ 20 смет из уже распарсенных и проверенных)</li><li>Метрика прогона не хуже текущей версии → активация; хуже → доработка</li><li>Деградация в проде → rollback на предыдущую версию (механизм есть), инцидент фиксируется</li><li>Право изменения — только Admin (NFR [[BRD (Agelto)]] §5)</li></ol><p>⚠️ Шаги 2–3 требуют тулинга (artisan-команда прогона по датасету) — не реализовано.</p><h3 id="_5-7-оркестрация-и-state-machine" tabindex="-1">5.7 Оркестрация и state machine <a class="header-anchor" href="#_5-7-оркестрация-и-state-machine" aria-label="Permalink to &quot;5.7 Оркестрация и state machine&quot;">​</a></h3><p>Статусы документа — enum <code>AnalysisStatus</code> (<code>app/Enums/AnalysisStatus.php</code>), 11 значений по фазам:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Фаза</th><th style="text-align:left;">Статусы</th></tr></thead><tbody><tr><td style="text-align:left;">Подготовка</td><td style="text-align:left;"><code>Preparing</code>, <code>Prepared</code></td></tr><tr><td style="text-align:left;">AI-скрининг</td><td style="text-align:left;"><code>PrimaryAnalyzing</code>, <code>PrimaryAnalyzed</code>, <code>PrimaryIgnored</code>, <code>PrimaryAnalysisFailed</code></td></tr><tr><td style="text-align:left;">Парсинг сметы</td><td style="text-align:left;"><code>EstimateAnalyzing</code>, <code>EstimateAnalyzed</code>, <code>EstimateAnalysisFailed</code></td></tr><tr><td style="text-align:left;">Завершение</td><td style="text-align:left;"><code>Completed</code></td></tr><tr><td style="text-align:left;">Ошибки</td><td style="text-align:left;"><code>Error</code></td></tr></tbody></table><p>Принципы (реализованы в коде):</p><ul><li>Переходы только через <code>DocumentAnalysis::transitionStatus()</code>; каждый переход пишется в <code>plt_document_analysis_logs</code></li><li>Idempotency: job проверяет текущий статус перед работой — повторная постановка не дублирует обработку</li><li>Цепочка стадий: <code>Bus::chain()</code> afterCommit; <code>failed()</code> job&#39;а переводит документ в failed-статус + Telegram-уведомление (<code>PipelineFailedNotification</code>)</li><li>Счётчик <code>attempts</code> и <code>last_error</code> — на записи документа</li></ul><hr><h2 id="_6-модуль-eis-—-парсер-zakupki-gov-ru" tabindex="-1">6. Модуль Eis — Парсер zakupki.gov.ru <a class="header-anchor" href="#_6-модуль-eis-—-парсер-zakupki-gov-ru" aria-label="Permalink to &quot;6. Модуль Eis — Парсер zakupki.gov.ru&quot;">​</a></h2><h3 id="_6-1-логика-eiscrawlingservice" tabindex="-1">6.1 Логика EisCrawlingService <a class="header-anchor" href="#_6-1-логика-eiscrawlingservice" aria-label="Permalink to &quot;6.1 Логика EisCrawlingService&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startHook(url)</span></span>
<span class="line"><span>  ├─ Если задан диапазон дат → цикл по дням → priceSplitHook(day_url)</span></span>
<span class="line"><span>  └─ Если нет → priceSplitHook(url)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>priceSplitHook(url)</span></span>
<span class="line"><span>  ├─ total_records из HTML</span></span>
<span class="line"><span>  ├─ Если 0 → выход</span></span>
<span class="line"><span>  ├─ Если &gt; 1000 → бинарный поиск по ценам (мин. дистанция: 10 000 ₽)</span></span>
<span class="line"><span>  └─ Если ≤ 1000 → processAllIntervalPages(url)</span></span></code></pre></div><h3 id="_6-2-crawlingitemdto" tabindex="-1">6.2 CrawlingItemDto <a class="header-anchor" href="#_6-2-crawlingitemdto" aria-label="Permalink to &quot;6.2 CrawlingItemDto&quot;">​</a></h3><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CrawlingItemDto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  externalId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;.registry-entry__header-mid__number&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">subject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">price</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">publishedAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">updatedAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">submissionEndAt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="_7-схема-данных-—-заказы-и-клиенты" tabindex="-1">7. Схема данных — Заказы и клиенты <a class="header-anchor" href="#_7-схема-данных-—-заказы-и-клиенты" aria-label="Permalink to &quot;7. Схема данных — Заказы и клиенты&quot;">​</a></h2><h3 id="_7-1-заказчики-заказы-лоты-объекты-закупки" tabindex="-1">7.1 Заказчики / Заказы / Лоты / Объекты закупки <a class="header-anchor" href="#_7-1-заказчики-заказы-лоты-объекты-закупки" aria-label="Permalink to &quot;7.1 Заказчики / Заказы / Лоты / Объекты закупки&quot;">​</a></h3><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><div class="note custom-block github-alert"><p class="custom-block-title">Разрывы (→ [[Procurement_Lifecycle]], [[ADR-002_Winner_Tracking_And_Monitoring|ADR-002]])</p><p></p><ul><li>Связи <code>ord_orders ↔ plt_crawler_links</code> нет — Стадия 5 (<code>OrderParsing</code>) не подключена, нормализованный результат смет не заполняется.</li><li>Полей победителя/контракта и <code>monitoring_status</code> нет — статус закупки в ЕИС после краулинга не отслеживается (предложено в ADR-002).</li></ul></div><h3 id="_7-2-геолокация" tabindex="-1">7.2 Геолокация <a class="header-anchor" href="#_7-2-геолокация" aria-label="Permalink to &quot;7.2 Геолокация&quot;">​</a></h3><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><h3 id="_7-3-эталонныи-каталог-внешнии-из-tcenzor" tabindex="-1">7.3 Эталонный каталог (внешний, из [[TcenZor]]) <a class="header-anchor" href="#_7-3-эталонныи-каталог-внешнии-из-tcenzor" aria-label="Permalink to &quot;7.3 Эталонный каталог (внешний, из [[TcenZor]])&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">Референс-каталог Agelto не строит</p><p>По [[ADR-001_Catalog_From_TcenZor|ADR-001]] эталонный строительный каталог приходит из [[TcenZor]] по API ([[Universal_Catalog_Architecture]]). Agelto хранит <strong>локальную реплику/кэш</strong> строительного среза для матчинга (базовый режим — offline-replica; <code>POST /catalog/match</code> к TcenZor — опция). Полная модель эталона — [[Universal_Catalog_Model]].</p></div><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><h3 id="_7-4-клиентские-коллекции-матчинг-домен-agelto" tabindex="-1">7.4 Клиентские коллекции + матчинг (домен Agelto) <a class="header-anchor" href="#_7-4-клиентские-коллекции-матчинг-домен-agelto" aria-label="Permalink to &quot;7.4 Клиентские коллекции + матчинг (домен Agelto)&quot;">​</a></h3><div class="warning custom-block github-alert"><p class="custom-block-title">Статус: SQL-проект, в коде не реализовано</p><p>Ни таблиц, ни моделей, ни pgvector-расширения в миграциях нет. Схема ниже — проект.</p></div><blockquote><p>📦 Полная схема перенесена в [[Database_Schema (Agelto)]]</p></blockquote><div class="note custom-block github-alert"><p class="custom-block-title">Изменение схемы matches</p><p>Раньше <code>matches</code> связывал <code>purchase_object_id</code> ↔ <code>collection_item_id</code> напрямую. По [[ADR-001_Catalog_From_TcenZor|ADR-001]] добавляется <code>catalog_product_id</code> — позиция сметы сопоставляется с эталоном, а коллекция клиента подбирается уже через эталон. Это даёт трассируемость и переиспользование алиасов.</p></div><hr><h2 id="_8-ai-паиплаин-—-детали-реализации" tabindex="-1">8. AI-пайплайн — детали реализации <a class="header-anchor" href="#_8-ai-паиплаин-—-детали-реализации" aria-label="Permalink to &quot;8. AI-пайплайн — детали реализации&quot;">​</a></h2><h3 id="_8-1-geminiservice" tabindex="-1">8.1 GeminiService <a class="header-anchor" href="#_8-1-geminiservice" aria-label="Permalink to &quot;8.1 GeminiService&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Метод</th><th style="text-align:left;">Назначение</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ensureFileInCloud(analysis)</code></td><td style="text-align:left;">Загружает файл в Google Files API</td></tr><tr><td style="text-align:left;"><code>getContextCache(analysis, instruction, ttlHours)</code></td><td style="text-align:left;">Создаёт/обновляет контекстный кэш (TTL по умолчанию 6 ч)</td></tr><tr><td style="text-align:left;"><code>generateJson(prompt, data, instruction?, cacheId?)</code></td><td style="text-align:left;">Генерирует JSON-ответ</td></tr><tr><td style="text-align:left;"><code>deleteCache(analysis)</code></td><td style="text-align:left;">Освобождает кэш после парсинга</td></tr></tbody></table><p><strong>Инвалидация кэша:</strong> fingerprint файла = <code>md5(file_name + size + mtime)</code>; смена fingerprint или hash активных PromptRules → кэш сбрасывается и пересоздаётся.</p><p><strong>Двухрежимный анализ (соответствие стадиям пайплайна §1):</strong></p><ul><li><strong>PrimaryAnalysis (стадия 3)</strong> — быстрый запрос без кэша: «есть ли смета?»</li><li><strong>EstimateAnalysis (стадия 4)</strong> — через контекстный кэш: извлечение всех позиций чанками</li></ul><h3 id="_8-2-smetaparserservice-excel" tabindex="-1">8.2 SmetaParserService (Excel) <a class="header-anchor" href="#_8-2-smetaparserservice-excel" aria-label="Permalink to &quot;8.2 SmetaParserService (Excel)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Загрузить Excel (PhpSpreadsheet)</span></span>
<span class="line"><span>2. Первые 100 строк → HTML → Gemini → структура шапки</span></span>
<span class="line"><span>3. Локализовать шапку по якорям (findHeaderCoords)</span></span>
<span class="line"><span>4. Чанки по 80 строк → Gemini: &quot;Распарси JSON&quot;</span></span>
<span class="line"><span>5. Собрать Item[] с типами SECTION | ITEM</span></span></code></pre></div><h3 id="_8-3-ai-стек-эволюция" tabindex="-1">8.3 AI-стек эволюция <a class="header-anchor" href="#_8-3-ai-стек-эволюция" aria-label="Permalink to &quot;8.3 AI-стек эволюция&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Стадия</th><th style="text-align:left;">Технология</th><th style="text-align:left;">Статус</th></tr></thead><tbody><tr><td style="text-align:left;">PDF-анализ</td><td style="text-align:left;">Gemini 2.0 Flash (Google Files API)</td><td style="text-align:left;">✅ рабочий</td></tr><tr><td style="text-align:left;">Excel-парсинг</td><td style="text-align:left;">Gemini 2.0 Flash (direct prompt)</td><td style="text-align:left;">✅ рабочий</td></tr><tr><td style="text-align:left;">Semantic matching</td><td style="text-align:left;">pgvector + BERT/E5 embeddings</td><td style="text-align:left;">🔧 в разработке</td></tr><tr><td style="text-align:left;">OCR для сканов</td><td style="text-align:left;">LayoutLMv3 / TrOCR</td><td style="text-align:left;">❌ планируется v2</td></tr><tr><td style="text-align:left;">Языковой комплаенс</td><td style="text-align:left;">BERT дообученный (лат ↔ кир)</td><td style="text-align:left;">❌ планируется v2</td></tr></tbody></table><p><strong>Рекомендуемая модель</strong>: <code>intfloat/multilingual-e5-large</code> для русскоязычного матчинга.</p><div class="info custom-block github-alert"><p class="custom-block-title">Стратегия независимости от Gemini</p><p>Полная стратегия fallback-провайдеров (RU-облака YandexGPT/GigaChat + локальная LLM), cost-метрики и roadmap миграции — [[LLM_Strategy]]. Закрывает риски блокировки Gemini (R-6) и 152-ФЗ (R-5).</p></div><hr><h2 id="_9-crm-интеграция" tabindex="-1">9. CRM-интеграция <a class="header-anchor" href="#_9-crm-интеграция" aria-label="Permalink to &quot;9. CRM-интеграция&quot;">​</a></h2><h3 id="_9-1-целевые-crm" tabindex="-1">9.1 Целевые CRM <a class="header-anchor" href="#_9-1-целевые-crm" aria-label="Permalink to &quot;9.1 Целевые CRM&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">CRM</th><th style="text-align:left;">Приоритет</th><th style="text-align:left;">Метод</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Bitrix24</strong></td><td style="text-align:left;">P1</td><td style="text-align:left;">REST API / Webhooks</td></tr><tr><td style="text-align:left;"><strong>amoCRM</strong></td><td style="text-align:left;">P1</td><td style="text-align:left;">REST API</td></tr><tr><td style="text-align:left;"><strong>1С:ERP</strong></td><td style="text-align:left;">P2</td><td style="text-align:left;">XML обмен</td></tr></tbody></table><h3 id="_9-2-структура-лида-в-crm" tabindex="-1">9.2 Структура лида в CRM <a class="header-anchor" href="#_9-2-структура-лида-в-crm" aria-label="Permalink to &quot;9.2 Структура лида в CRM&quot;">​</a></h3><blockquote><p>📦 Полный контракт перенесён в [[API_Endpoints (Agelto)]]</p></blockquote><hr><h2 id="_10-инфраструктура" tabindex="-1">10. Инфраструктура <a class="header-anchor" href="#_10-инфраструктура" aria-label="Permalink to &quot;10. Инфраструктура&quot;">​</a></h2><h3 id="_10-1-очереди-horizon-—-реальные-из-кода" tabindex="-1">10.1 Очереди (Horizon) — реальные, из кода <a class="header-anchor" href="#_10-1-очереди-horizon-—-реальные-из-кода" aria-label="Permalink to &quot;10.1 Очереди (Horizon) — реальные, из кода&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Очередь</th><th style="text-align:left;">Job</th><th style="text-align:left;">Timeout</th><th style="text-align:left;">Retries</th></tr></thead><tbody><tr><td style="text-align:left;"><code>platform_document_prepare</code></td><td style="text-align:left;"><code>PrepareDocumentJob</code></td><td style="text-align:left;">300 сек</td><td style="text-align:left;">3</td></tr><tr><td style="text-align:left;"><code>platform_primary_analysis</code></td><td style="text-align:left;"><code>PrimaryAnalysisJob</code></td><td style="text-align:left;">180 сек</td><td style="text-align:left;">5</td></tr><tr><td style="text-align:left;"><code>platform_estimate_analysis</code></td><td style="text-align:left;"><code>EstimateAnalysisJob</code></td><td style="text-align:left;">300 сек</td><td style="text-align:left;">3</td></tr></tbody></table><p>Очереди <code>matching</code> и <code>notifications</code> (CRM) — появятся вместе с соответствующими модулями (не начаты).</p><h3 id="_10-2-docker-compose" tabindex="-1">10.2 Docker Compose <a class="header-anchor" href="#_10-2-docker-compose" aria-label="Permalink to &quot;10.2 Docker Compose&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># dev (docker-compose.yml)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PHP 8.5 / Laravel + nginx</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  vite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frontend dev server</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  docs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># VitePress</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  horizon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># queue worker</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pgsql</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PostgreSQL 15</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  redis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># кэш + очереди</span></span></code></pre></div><p>Prod (<code>docker-compose.prod.yml</code>): image-based деплой, Docker Swarm secrets (app_key, db_password, redis_password), health checks, auto-restart.</p><p>⚠️ CI/CD-конвейер и staging-окружение не описаны — [[Открытые вопросы (Agelto)]] T9.</p><hr><h2 id="_11-конвенции-разработки-из-кода" tabindex="-1">11. Конвенции разработки (из кода) <a class="header-anchor" href="#_11-конвенции-разработки-из-кода" aria-label="Permalink to &quot;11. Конвенции разработки (из кода)&quot;">​</a></h2><p>Зафиксированы в <code>.ai/guidelines/</code> репозитория, синхронизация — <code>composer ai:sync</code> → CLAUDE.md.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Конвенция</th><th style="text-align:left;">Где</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Processor pattern</strong> — бизнес-логика стадий в <code>app/Process/*/Processor.php</code>, не в контроллерах</td><td style="text-align:left;"><code>DocumentProcessor</code>, <code>PrimaryAnalysisProcessor</code>, <code>EstimateAnalysisProcessor</code></td></tr><tr><td style="text-align:left;"><strong>DTO</strong> — типизированные структуры (spatie/laravel-data) для всех данных между слоями</td><td style="text-align:left;"><code>app/Dto/</code> (<code>CrawlingItemDto</code>, <code>PrimaryAnalysisResponse</code>, …)</td></tr><tr><td style="text-align:left;"><strong>Repositories</strong> — query-логика отдельно от моделей</td><td style="text-align:left;"><code>app/Repositories/</code></td></tr><tr><td style="text-align:left;"><strong>Enums</strong> — статусы и стадии только через enum</td><td style="text-align:left;"><code>AnalysisStatus</code>, <code>ProcessStage</code>, <code>CrawlingStatus</code></td></tr><tr><td style="text-align:left;"><strong>Named arguments</strong> — все вызовы методов с именованными аргументами</td><td style="text-align:left;"><code>.ai/guidelines/php-coding-standards.md</code></td></tr><tr><td style="text-align:left;"><strong>Транзакции</strong> — multi-step операции в <code>DB::transaction()</code></td><td style="text-align:left;">guideline architecture.md</td></tr><tr><td style="text-align:left;"><strong>Тесты</strong> — Pest v4, architecture tests (presets PHP/Security/Laravel), larastan</td><td style="text-align:left;"><code>tests/</code></td></tr></tbody></table><p>Документация в коде: <code>docs/dev/architecture.md</code>, <code>docs/workflow/parsing-process.md</code> (VitePress) — поддерживать синхронно с этим файлом.</p><hr><h2 id="_12-observability" tabindex="-1">12. Observability <a class="header-anchor" href="#_12-observability" aria-label="Permalink to &quot;12. Observability&quot;">​</a></h2><p><strong>Текущее состояние (код):</strong></p><ul><li>Telegram-уведомления о сбоях пайплайна (<code>PipelineFailedNotification</code>, custom <code>TelegramChannel</code>)</li><li><code>sys_logs</code> (AppLogger: Console/DB) + лог переходов state machine (<code>plt_document_analysis_logs</code>)</li><li>Метрика кроулера <code>items_count</code> (аларм-сигнал «ЕИС сменил вёрстку» — BRD §6)</li></ul><p><strong>Целевое (не реализовано, → [[Открытые вопросы (Agelto)]] T5):</strong></p><ul><li>Метрики стадий пайплайна: время в очереди, длительность, error rate per стадия</li><li>Cost-метрики Gemini: токены/документ, ₽/смета — входной параметр unit-экономики тарифов ([[Risk_Register (Agelto)]] R-7)</li><li>SLO по NFR из [[BRD (Agelto)]] §5 (скрининг ≤ 5 мин, freshness ≤ 4 ч) + алерты на нарушение</li><li>Дашборд (кандидаты: Horizon metrics + Laravel Pulse / Grafana)</li></ul><hr><h2 id="_13-dr-backup" tabindex="-1">13. DR / Backup <a class="header-anchor" href="#_13-dr-backup" aria-label="Permalink to &quot;13. DR / Backup&quot;">​</a></h2><p>Не реализовано; требования (→ [[Открытые вопросы (Agelto)]] T7):</p><ul><li>Автоматический backup PostgreSQL (расписание, retention, проверка восстановления)</li><li>Хранение оригиналов PDF/XLS: сейчас локальный диск через Spatie Media Library; целевое — S3-совместимое хранилище ([[03_Financial_Model]] §7)</li><li>Целевые RPO/RTO — определить; данные восстановимы повторным кроулингом ЕИС, но история анализов и будущие коллекции клиентов — нет</li></ul><hr><h2 id="_14-масштабирование-и-rate-limiting" tabindex="-1">14. Масштабирование и rate limiting <a class="header-anchor" href="#_14-масштабирование-и-rate-limiting" aria-label="Permalink to &quot;14. Масштабирование и rate limiting&quot;">​</a></h2><ul><li><strong>Квоты Gemini:</strong> лимиты API не специфицированы; нужен бюджет токенов и поведение при превышении (BRD §6: backoff + алерт)</li><li><strong>Параллелизм очередей:</strong> настройка воркеров Horizon per-очередь; ограничитель параллельных запросов к Gemini</li><li><strong>Прокси-пул</strong> (Sys) — ограниченный ресурс кроулинга: мониторинг живости и ёмкости</li><li><strong>Векторный поиск:</strong> pgvector достаточен до ~10M записей; партиционирование/Qdrant — при росте (§15)</li><li><strong>БД:</strong> шардинг по клиентам — после 100+ клиентов (см. вопрос мультитенантности)</li></ul><hr><h2 id="_15-открытые-архитектурные-вопросы" tabindex="-1">15. Открытые архитектурные вопросы <a class="header-anchor" href="#_15-открытые-архитектурные-вопросы" aria-label="Permalink to &quot;15. Открытые архитектурные вопросы&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Вопрос</th><th style="text-align:left;">Рекомендация</th></tr></thead><tbody><tr><td style="text-align:left;">ЕИС Web vs FTP XML feeds?</td><td style="text-align:left;">HTTP текущая реализация; FTP-feeds/SOAP API — v2; статус доступа ⚠️ непроверен → [[Procurement_Lifecycle]] §10</td></tr><tr><td style="text-align:left;">Отслеживание результата закупки/победителя?</td><td style="text-align:left;">🟡 Предложено ([[ADR-002_Winner_Tracking_And_Monitoring|ADR-002]]), требует бизнес-валидации; HTML-карточка vs SOAP — открытый под-вопрос</td></tr><tr><td style="text-align:left;">BERT/E5 модель для embeddings?</td><td style="text-align:left;"><code>intfloat/multilingual-e5-large</code> (1024-dim, поддержка рус.)</td></tr><tr><td style="text-align:left;">pgvector vs Qdrant для матчинга?</td><td style="text-align:left;">pgvector достаточен до 10M+ записей; Qdrant при &gt;50M</td></tr><tr><td style="text-align:left;">Обработка сканированных PDF?</td><td style="text-align:left;">LayoutLMv3 / TrOCR или Qwen2.5-VL / olmOCR 2 — нужна GPU (v2) → [[LLM_Strategy]] разд. 11</td></tr><tr><td style="text-align:left;">Мультитенантность?</td><td style="text-align:left;">Row-level security в PostgreSQL → шардинг при &gt;100 клиентах</td></tr><tr><td style="text-align:left;">Тарификация Gemini-запросов для клиентов?</td><td style="text-align:left;">Квота смет/месяц → лимит в PromptRule options</td></tr><tr><td style="text-align:left;">Стек observability (§12)?</td><td style="text-align:left;">Кандидат: Horizon + Laravel Pulse на старте, Grafana при росте — [[Открытые вопросы (Agelto)]] T5</td></tr><tr><td style="text-align:left;">Биллинг и учёт квот?</td><td style="text-align:left;">Счётчики + audit trail (BRD F-MON-1/3) — механизм не выбран — [[Открытые вопросы (Agelto)]] T6</td></tr><tr><td style="text-align:left;">RPO/RTO и backup (§13)?</td><td style="text-align:left;">[[Открытые вопросы (Agelto)]] T7</td></tr><tr><td style="text-align:left;">Gemini vs 152-ФЗ / fallback-провайдер?</td><td style="text-align:left;">🔴 ProviderRouter + RU-fallback + резолюция L3 → [[LLM_Strategy]] разд. 4–5 ([[Risk_Register (Agelto)]] R-5, R-6)</td></tr></tbody></table>`,117)])])}const y=e(i,[["render",n]]);export{g as __pageData,y as default};
